def level_of_service(m2_each):
    for grade, limit in [('A', 3.25), ('B', 2.32), ('C', 1.39), ('D', 0.93), ('E', 0.46)]:
        if m2_each >= limit:
            return grade
    return 'F'

for people, area in [(30, 120), (120, 60), (600, 400), (300, 100)]:
    rho = people / area
    print(f'{people:4d} people in {area:4d} m2: {rho:.2f} per m2, {1/rho:.2f} m2 each, LOS {level_of_service(1/rho)}')
